"use client";
import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject,
} from "react";
import { motion } from "motion/react";
import {
  sectionStyles,
  useSectionEnvironment,
  useSectionScroll,
  type SectionInternalGroup,
  type SectionInternalLink,
} from "./section-shared";
export interface DockFooterLink extends SectionInternalLink {}
export interface DockFooterGroup extends SectionInternalGroup {}
export interface DockFooterProps {
  brand: ReactNode;
  groups: readonly DockFooterGroup[];
  headline?: ReactNode;
  description?: ReactNode;
  copyright?: ReactNode;
  children?: ReactNode;
  background?: string;
  backgroundImage?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onNavigate?: (link: DockFooterLink) => void;
  autoOpen?: boolean;
  duration?: number;
  revealDistance?: number;
  scrollContainer?: RefObject<HTMLElement | null>;
  onProgress?: (progress: number) => void;
  height?: number;
  className?: string;
  style?: CSSProperties;
}
/** Footer uncovered on scroll with a translucent expanding quick-navigation dock. */
export function DockFooter({
  brand,
  groups,
  headline,
  description,
  copyright,
  children,
  background = "#353710",
  backgroundImage,
  open,
  defaultOpen = false,
  onOpenChange,
  onNavigate,
  autoOpen = true,
  duration = 0.65,
  revealDistance = 620,
  scrollContainer,
  onProgress,
  height = 720,
  className = "",
  style,
}: DockFooterProps) {
  const env = useSectionEnvironment(),
    progress = useSectionScroll(env.ref, scrollContainer, onProgress),
    [local, setLocal] = useState(defaultOpen),
    bottom = progress >= 0.985,
    atBottom = useRef(false),
    expanded = open ?? local;
  const change = (next: boolean) => {
    if (open === undefined) setLocal(next);
    onOpenChange?.(next);
  };
  useEffect(() => {
    if (bottom && !atBottom.current && autoOpen) {
      if (open === undefined) setLocal(true);
      onOpenChange?.(true);
    }
    atBottom.current = bottom;
  }, [bottom, autoOpen, open, onOpenChange]);
  const t = {
      duration: env.reduced ? 0 : Math.max(0, duration),
      ease: [0.22, 0.8, 0.2, 1] as const,
    },
    links = groups.flatMap((group) => group.links).slice(0, 6);
  return (
    <div
      ref={env.ref}
      className={`z-as z-as-dock-footer ${className}`}
      data-section="dock-footer"
      data-progress={progress.toFixed(4)}
      data-open={expanded}
      style={
        {
          height: `calc(min(${height}px,100svh) + ${Math.max(0, revealDistance)}px)`,
          "--section-height": `${height}px`,
          ...style,
        } as CSSProperties
      }
    >
      <style>
        {sectionStyles +
          `.z-as-dock-footer{overflow-anchor:none}.z-as-dock-footer .z-as-footer-surface{height:100%;position:absolute;inset:0;color:#efeee4;overflow:hidden;padding:40px 3.2%}.z-as-dock-footer .z-as-footer-columns{position:relative;display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:35px}.z-as-dock-footer .z-as-footer-brand{font-size:44px;font-weight:800;font-style:italic;letter-spacing:-.06em;line-height:1}.z-as-dock-footer .z-as-footer-message h2{font-size:clamp(28px,4vw,44px);font-weight:400;line-height:1.15;letter-spacing:-.04em;margin:28px 0 24px;max-width:300px}.z-as-dock-footer .z-as-footer-message p{max-width:330px;font-size:13px;opacity:.65}.z-as-dock-footer .z-as-links h3{opacity:.5;font-weight:400;font-size:12px}.z-as-dock-footer .z-as-links a{font-size:14px}.z-as-dock-footer .z-as-footer-bottom{position:absolute;left:3.2%;right:3.2%;bottom:20px;border-top:1px solid #fff2;padding-top:12px;opacity:.6;font-size:11px}.z-as-dock-footer .z-as-dock{position:absolute;z-index:6;bottom:60px;left:50%;max-width:calc(100% - 32px);transform:translateX(-50%);padding:6px;background:#ffffff18;backdrop-filter:blur(20px);border:1px solid #ffffff28;border-radius:28px;color:#eeeee8;overflow:hidden}.z-as-dock-footer .z-as-dock-header{display:flex;gap:8px;justify-content:center;align-items:center}.z-as-dock-footer .z-as-dock-header button{height:40px;border-radius:30px;background:#ffffff18;padding:0 15px;white-space:nowrap}.z-as-dock-footer .z-as-dock-links{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;padding:14px 10px}.z-as-dock-footer .z-as-dock-links a{font-size:13px;text-decoration:none;padding:8px 10px;border-radius:8px}.z-as-dock-footer .z-as-dock-links a:hover{background:#fff1}.z-as-dock-footer .z-as-footer-cover{position:absolute;inset:0;background:#efefef;z-index:3;display:flex;align-items:center;justify-content:center;color:#888;text-align:center;pointer-events:none}.z-as-dock-footer .z-as-footer-cover small{position:absolute;bottom:28px;letter-spacing:.2em;font-size:10px}@media(max-width:600px){.z-as-dock-footer .z-as-footer-surface{padding:25px 20px}.z-as-dock-footer .z-as-footer-columns{grid-template-columns:repeat(3,1fr);gap:14px}.z-as-dock-footer .z-as-footer-message{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:12px}.z-as-dock-footer .z-as-footer-brand{font-size:30px}.z-as-dock-footer .z-as-footer-message h2{margin:0;font-size:24px}.z-as-dock-footer .z-as-footer-message p{grid-column:1/-1;font-size:12px}.z-as-dock-footer .z-as-links a{font-size:12px}.z-as-dock-footer .z-as-dock{bottom:50px}}`}
      </style>
      <div className="z-as-pin">
        <footer
          className="z-as-footer-surface"
          inert={progress <= 0 && revealDistance > 0}
          style={{
            background,
            transform: `translateY(${env.reduced ? 0 : (1 - progress) * 80}px)`,
          }}
          onKeyDown={(event) => {
            if (event.key === "Escape") change(false);
          }}
        >
          {backgroundImage && (
            <img
              src={backgroundImage}
              alt=""
              className="z-as-fill"
              style={{
                opacity: 0.18,
                filter: "blur(10px)",
                transform: "scale(1.1)",
              }}
            />
          )}
          <div className="z-as-footer-columns">
            <div className="z-as-footer-message">
              <div className="z-as-footer-brand">{brand}</div>
              <h2>{headline}</h2>
              <p>{description}</p>
            </div>
            {groups.map((group, i) => (
              <motion.div
                key={group.title}
                className="z-as-links"
                initial={false}
                animate={{
                  y: progress > 0.15 || env.reduced ? 0 : 35,
                  opacity: progress > 0.1 || env.reduced ? 1 : 0,
                }}
                transition={{ ...t, delay: env.reduced ? 0 : i * 0.07 }}
              >
                <h3>{group.title}</h3>
                {group.links.map((link) => (
                  <a
                    key={link.href + link.label}
                    href={link.href}
                    onClick={() => onNavigate?.(link)}
                  >
                    {link.label}
                  </a>
                ))}
              </motion.div>
            ))}
          </div>
          <div className="z-as-footer-bottom">{copyright}</div>
          <motion.div
            className="z-as-dock"
            animate={{ width: expanded ? 310 : 180 }}
            transition={t}
          >
            <motion.div
              className="z-as-dock-links"
              initial={false}
              animate={{
                height: expanded ? "auto" : 0,
                opacity: expanded ? 1 : 0,
                paddingTop: expanded ? 14 : 0,
                paddingBottom: expanded ? 14 : 0,
              }}
              transition={t}
              aria-hidden={!expanded}
              inert={!expanded}
              style={{
                overflow: "hidden",
                pointerEvents: expanded ? "auto" : "none",
              }}
            >
              {links.map((link) => (
                <a
                  key={link.href + link.label}
                  href={link.href}
                  tabIndex={expanded ? 0 : -1}
                  onClick={() => {
                    onNavigate?.(link);
                    change(false);
                  }}
                >
                  {link.label} ↗
                </a>
              ))}
            </motion.div>
            <div className="z-as-dock-header">
              <button
                type="button"
                aria-label={
                  expanded ? "Close quick navigation" : "Open quick navigation"
                }
                aria-expanded={expanded}
                onClick={() => change(!expanded)}
              >
                Menu {expanded ? "−" : "+"}
              </button>
              <button
                type="button"
                aria-label="Back to top"
                onClick={() => {
                  const container = scrollContainer?.current;
                  (container ?? window).scrollTo({
                    top: 0,
                    behavior: env.reduced ? "instant" : "smooth",
                  });
                }}
              >
                ↑
              </button>
            </div>
          </motion.div>
        </footer>
        <div
          className="z-as-footer-cover"
          style={{ transform: `translateY(${-progress * 110}%)` }}
        >
          {children}
          <small>SCROLL ↓</small>
        </div>
      </div>
    </div>
  );
}

// @zeus-internal
export const sectionClamp = (value: number, min = 0, max = 1) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : 0));
export const sectionWrap = (value: number, count: number) =>
  count > 0 ? ((value % count) + count) % count : 0;
export type SectionPoint = readonly [number, number, number];
export function spherePoint(latitude: number, longitude: number): SectionPoint {
  const lat = (latitude * Math.PI) / 180,
    lon = (longitude * Math.PI) / 180;
  return [
    Math.cos(lat) * Math.sin(lon),
    -Math.sin(lat),
    Math.cos(lat) * Math.cos(lon),
  ];
}
export function rotatePoint(
  [x, y, z]: SectionPoint,
  yaw: number,
  pitch: number,
): SectionPoint {
  const xx = x * Math.cos(yaw) + z * Math.sin(yaw),
    zz = z * Math.cos(yaw) - x * Math.sin(yaw);
  return [
    xx,
    y * Math.cos(pitch) - zz * Math.sin(pitch),
    zz * Math.cos(pitch) + y * Math.sin(pitch),
  ];
}
export function fibonacciPoint(index: number, count: number): SectionPoint {
  const y = 1 - (2 * (index + 0.5)) / Math.max(1, count),
    r = Math.sqrt(1 - y * y),
    angle = index * Math.PI * (3 - Math.sqrt(5));
  return [Math.cos(angle) * r, y, Math.sin(angle) * r];
}

// @zeus-internal
"use client";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  type PointerEvent,
} from "react";
import { sectionClamp, sectionWrap } from "./section-math";
export interface SectionInternalMedia {
  src?: string;
  alt?: string;
  content?: ReactNode;
}
export interface SectionInternalItem extends SectionInternalMedia {
  id: string;
  title: string;
  description?: string;
}
export interface SectionInternalBase {
  className?: string;
  style?: CSSProperties;
  height?: number;
  label?: string;
}
export interface SectionInternalLink {
  label: string;
  href: string;
}
export interface SectionInternalGroup {
  title: string;
  links: readonly SectionInternalLink[];
}
export function useSectionEnvironment() {
  const ref = useRef<HTMLDivElement>(null),
    [size, setSize] = useState({ width: 1000, height: 640 }),
    [active, setActive] = useState(false),
    [reduced, setReduced] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    let visible = true;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      setActive(visible && !document.hidden);
      setReduced(media.matches);
    };
    const resize = () =>
      setSize({
        width: node.clientWidth || 1000,
        height: node.clientHeight || 640,
      });
    const ro =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize);
    ro?.observe(node);
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver((entries) => {
            visible = entries[0]?.isIntersecting ?? true;
            update();
          });
    io?.observe(node);
    media.addEventListener("change", update);
    document.addEventListener("visibilitychange", update);
    resize();
    update();
    return () => {
      ro?.disconnect();
      io?.disconnect();
      media.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", update);
    };
  }, []);
  return { ref, size, active, reduced };
}
export function useSectionLoop(
  active: boolean,
  callback: (delta: number) => void,
) {
  const latest = useRef(callback);
  latest.current = callback;
  useEffect(() => {
    if (!active) return;
    let frame = 0,
      last = 0;
    const tick = (now: number) => {
      const delta = last ? Math.min(0.04, (now - last) / 1000) : 0;
      last = now;
      latest.current(delta);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active]);
}
export function useSectionSelection(
  count: number,
  index: number | undefined,
  defaultIndex: number,
  onChange?: (index: number) => void,
) {
  const [local, setLocal] = useState(defaultIndex);
  const selected = sectionWrap(Math.round(index ?? local), count),
    current = useRef(selected);
  current.current = selected;
  const select = useCallback(
    (next: number) => {
      next = sectionWrap(Math.round(next), count);
      if (next === current.current) return;
      if (index === undefined) {
        current.current = next;
        setLocal(next);
      }
      onChange?.(next);
    },
    [count, index, onChange],
  );
  return { selected, select, current };
}
export function useSectionScroll(
  ref: RefObject<HTMLElement | null>,
  scrollContainer?: RefObject<HTMLElement | null>,
  onProgress?: (progress: number) => void,
) {
  const [progress, setProgress] = useState(0),
    latest = useRef(onProgress),
    previous = useRef(-1);
  latest.current = onProgress;
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    let frame = 0;
    const container = scrollContainer?.current;
    const measure = () => {
      frame = 0;
      const box = node.getBoundingClientRect(),
        top = container?.getBoundingClientRect().top ?? 0,
        view = container?.clientHeight ?? innerHeight;
      const next = sectionClamp(
        (top - box.top) / Math.max(1, box.height - view),
      );
      if (Math.abs(previous.current - next) >= 0.0001) {
        previous.current = next;
        setProgress(next);
        latest.current?.(next);
      }
    };
    const request = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    const target = container ?? window;
    target.addEventListener("scroll", request, { passive: true });
    window.addEventListener("resize", request);
    const ro =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(request);
    ro?.observe(node);
    measure();
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", request);
      window.removeEventListener("resize", request);
      ro?.disconnect();
    };
  }, [ref, scrollContainer]);
  return progress;
}
export function useSphereRotation(
  active: boolean,
  reduced: boolean,
  autoplay: boolean,
  speed: number,
  drag: boolean,
) {
  const state = useRef({
      yaw: 0,
      pitch: 0,
      vx: 0,
      vy: 0,
      target: null as null | { yaw: number; pitch: number },
    }),
    [rotation, setRotation] = useState({ yaw: 0, pitch: 0 }),
    pointer = useRef<null | { id: number; x: number; y: number; time: number }>(
      null,
    );
  const publish = () =>
    setRotation({ yaw: state.current.yaw, pitch: state.current.pitch });
  useSectionLoop(active && !reduced, (delta) => {
    const s = state.current;
    if (pointer.current) return;
    if (s.target) {
      const ease = 1 - Math.exp(-delta * 6);
      s.yaw += (s.target.yaw - s.yaw) * ease;
      s.pitch += (s.target.pitch - s.pitch) * ease;
      if (
        Math.abs(s.yaw - s.target.yaw) + Math.abs(s.pitch - s.target.pitch) <
        0.001
      )
        s.target = null;
    } else {
      s.yaw += (s.vx + (autoplay ? speed : 0)) * delta;
      s.pitch = sectionClamp(s.pitch + s.vy * delta, -1.2, 1.2);
      s.vx *= Math.exp(-delta * 5);
      s.vy *= Math.exp(-delta * 5);
    }
    publish();
  });
  const orient = useCallback(
    (yaw: number, pitch: number) => {
      const s = state.current;
      const shortest =
        ((((yaw - s.yaw + Math.PI) % (Math.PI * 2)) + Math.PI * 2) %
          (Math.PI * 2)) -
        Math.PI;
      s.vx = 0;
      s.vy = 0;
      if (reduced) {
        s.yaw += shortest;
        s.pitch = pitch;
        s.target = null;
        setRotation({ yaw: s.yaw, pitch: s.pitch });
      } else s.target = { yaw: s.yaw + shortest, pitch };
    },
    [reduced],
  );
  const end = (event: PointerEvent<HTMLElement>) => {
    if (pointer.current?.id !== event.pointerId) return;
    pointer.current = null;
    if (reduced) {
      state.current.vx = 0;
      state.current.vy = 0;
    }
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  };
  return {
    rotation,
    orient,
    handlers: {
      onPointerDown: (event: PointerEvent<HTMLElement>) => {
        if (
          !drag ||
          event.button !== 0 ||
          (event.target as HTMLElement).closest("button,a,input")
        )
          return;
        pointer.current = {
          id: event.pointerId,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        state.current.target = null;
        state.current.vx = state.current.vy = 0;
        event.currentTarget.setPointerCapture?.(event.pointerId);
      },
      onPointerMove: (event: PointerEvent<HTMLElement>) => {
        const p = pointer.current;
        if (!p || p.id !== event.pointerId) return;
        const dx = (event.clientX - p.x) * 0.006,
          dy = (event.clientY - p.y) * 0.006,
          dt = Math.max(0.008, (event.timeStamp - p.time) / 1000);
        state.current.yaw += dx;
        state.current.pitch = sectionClamp(state.current.pitch + dy, -1.2, 1.2);
        state.current.vx = sectionClamp(dx / dt, -5, 5);
        state.current.vy = sectionClamp(dy / dt, -3, 3);
        pointer.current = {
          id: p.id,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        publish();
      },
      onPointerUp: end,
      onPointerCancel: end,
      onLostPointerCapture: () => {
        pointer.current = null;
      },
    },
  };
}
export function SectionImage({
  item,
  className,
  style,
}: {
  item: SectionInternalMedia;
  className?: string;
  style?: CSSProperties;
}) {
  return item.content ? (
    <div className={className} style={style}>
      {item.content}
    </div>
  ) : item.src ? (
    <img
      className={className}
      style={style}
      src={item.src}
      alt={item.alt ?? ""}
      draggable={false}
    />
  ) : (
    <div className={className} style={style} />
  );
}
export const sectionStyles = `.z-as{position:relative;width:100%;box-sizing:border-box;isolation:isolate;background:#ebebe9;color:#171717;font:15px/1.5 Arial,Helvetica,sans-serif;--z-as-accent:#dfff00}.z-as *{box-sizing:border-box}.z-as h2,.z-as h3,.z-as p,.z-as figure{margin:0}.z-as button,.z-as a{font:inherit;color:inherit}.z-as button{cursor:pointer}.z-as button:focus-visible,.z-as a:focus-visible,.z-as:focus-visible{outline:3px solid #548bff;outline-offset:5px}.z-as button{border:0}.z-as img,.z-as video{display:block;width:100%;height:100%;object-fit:cover}.z-as .z-as-controls{display:flex;align-items:center;justify-content:center;gap:16px}.z-as .z-as-controls button{width:40px;height:40px;border-radius:50%;background:#ffffff18;flex:none}.z-as .z-as-pill{display:flex;align-items:center;gap:12px;padding:6px;border:1px solid #ffffff12;background:#30302fd9;backdrop-filter:blur(14px);border-radius:999px;color:#efeee9}.z-as .z-as-pill button{background:#ffffff12;border-radius:50%;width:40px;height:40px}.z-as .z-as-pill span{min-width:80px;text-align:center;font-size:13px}.z-as .z-as-heading{font-weight:400;line-height:1.05;letter-spacing:-.045em;font-size:clamp(32px,5vw,64px)}.z-as .z-as-fill{position:absolute;inset:0}.z-as .z-as-mask{overflow:hidden;display:block}.z-as .z-as-pin{position:sticky;top:0;height:min(var(--section-height,640px),100svh);min-height:420px;overflow:hidden}.z-as .z-as-links a{text-decoration:none;position:relative;width:fit-content;display:block;padding:5px 0}.z-as .z-as-links a:after{content:"";position:absolute;bottom:3px;left:0;right:0;height:1px;background:currentColor;transform:scaleX(0);transform-origin:right;transition:transform .35s}.z-as .z-as-links a:hover:after,.z-as .z-as-links a:focus-visible:after{transform:scaleX(1);transform-origin:left}@media(prefers-reduced-motion:reduce){.z-as *,.z-as *:before,.z-as *:after{animation-duration:0s!important;transition-duration:0s!important;scroll-behavior:auto!important}}`;
